import {getContent,contentAccess,previewContent,saveContent,uploadImage} from './content.js';
import {cleanContent,contentDefaults} from './content-schema.js';
import {projects} from './projects.js';
export function initEditor(dialog){
  let saved=getContent(),draft=getContent(),busy=false,dirty=false;
  const tabs=dialog.querySelector('.settings-tabs');
  const editor=document.createElement('section');editor.id='exhibition-settings';editor.hidden=true;
  editor.innerHTML=`<p class="editor-notice">전시 내용은 저장하면 방문자 모두에게 적용됩니다. 화면 크기와 움직임 선호는 내 브라우저에만 적용됩니다.</p><div class="editor-sections"><button type="button" data-editor-section="words" aria-pressed="true">문구</button><button type="button" data-editor-section="art">작품</button><button type="button" data-editor-section="character">캐릭터</button><button type="button" data-editor-section="space">공간</button></div><div id="editor-fields"></div><p id="editor-status" role="status"></p><div class="editor-actions"><button type="button" id="editor-preview">전체 화면 미리보기</button><button type="button" id="editor-discard">저장된 전시로 되돌리기</button><button type="button" id="editor-save" class="primary-link">전시 저장</button></div><details class="editor-backup"><summary>백업 · 가져오기 · 초기화</summary><button type="button" id="content-export">전시 설정 내보내기</button><label class="file-button">설정 가져오기<input type="file" id="content-import" accept="application/json,.json"></label><button type="button" id="content-reset">기본 전시 미리보기</button><p>내보낸 파일에는 문구·색상·이미지 주소가 포함됩니다. 같은 사이트에 다시 가져올 수 있습니다.</p></details>`;
  dialog.querySelector('#settings-status').before(editor);
  const tab=document.createElement('button');tab.type='button';tab.dataset.settingsTab='exhibition';tab.textContent='전시 편집';tab.setAttribute('aria-pressed','false');tabs.prepend(tab);
  const access=contentAccess(),status=editor.querySelector('#editor-status'),fields=editor.querySelector('#editor-fields');
  const say=(message,error=false)=>{status.textContent=message;status.classList.toggle('error',error)};
  function changed(){dirty=true;try{previewContent(draft);say('미리보기 중입니다. 전시 저장을 누르면 방문자에게 반영됩니다.')}catch(e){say(e.message,true)}}
  function field(label,key,multiline=false,object=draft){const wrap=document.createElement('label');wrap.className='editor-field';const name=document.createElement('span');name.textContent=label;const input=document.createElement(multiline?'textarea':'input');if(!multiline)input.type='text';input.value=object[key]??'';input.maxLength=multiline?1500:250;input.dataset.contentField=key;input.addEventListener('input',()=>{object[key]=input.value;changed()});wrap.append(name,input);fields.append(wrap);}
  function range(label,key,min,max,step){const wrap=document.createElement('label');wrap.className='editor-field range-field';const name=document.createElement('span');name.textContent=label;const input=document.createElement('input'),output=document.createElement('output');input.type='range';Object.assign(input,{min,max,step,value:draft[key]});output.textContent=draft[key]+'×';input.dataset.contentField=key;input.addEventListener('input',()=>{draft[key]=Number(input.value);output.textContent=draft[key]+'×';changed()});wrap.append(name,input,output);fields.append(wrap)}
  function image(label,key,object=draft,fallback=''){const box=document.createElement('div');box.className='editor-image';const caption=document.createElement('strong');caption.textContent=label;const img=document.createElement('img');img.alt=label+' 미리보기';img.src=object[key]||fallback;img.hidden=!img.src;const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/gif';input.setAttribute('aria-label',label+' 업로드');const reset=document.createElement('button');reset.type='button';reset.textContent='원래 이미지';reset.addEventListener('click',()=>{object[key]=fallback;img.src=fallback;img.hidden=!fallback;changed()});input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;busy=true;input.disabled=true;say('이미지를 올리고 있습니다…');try{object[key]=await uploadImage(file);img.src=object[key];img.hidden=false;changed()}catch(e){say(e.message,true)}finally{busy=false;input.disabled=false;input.value=''}});box.append(caption,img,input,reset);fields.append(box)}
  let section='words';
  function render(){fields.replaceChildren();if(section==='words'){field('사이트 이름','brand');field('작은 제목','eyebrow');field('메인 제목','title');field('메인 설명','description',true);field('소개','introduction',true);field('하단 문구','footer')}
    if(section==='character'){image('안내 캐릭터','character',draft,contentDefaults.character);const label=document.createElement('label');label.className='editor-field';const check=document.createElement('input');check.type='checkbox';check.checked=draft.characterVisible;check.addEventListener('change',()=>{draft.characterVisible=check.checked;changed()});label.append(check,document.createTextNode(' 캐릭터 표시'));fields.append(label);range('캐릭터 크기','characterSize',.4,2.5,.1);range('산책 속도','characterSpeed',0,2,.1)}
    if(section==='space'){for(const [label,key] of [['조명 포인트 색','accent'],['하늘 배경 색','room']]){field(label,key);const input=fields.lastElementChild.querySelector('input');input.type='color'}range('카메라 이동 속도','cameraSpeed',.5,2,.1);range('장면 밝기','lighting',.4,1.8,.1)}
    if(section==='art'){for(const p of projects){const heading=document.createElement('h3');heading.textContent=p.number+' / '+p.title;fields.append(heading);const value=draft.projects[p.id]??={title:p.title,subtitle:p.subtitle,description:p.description,image:p.image||'',link:''};field('작품 이름','title',false,value);field('한 줄 소개','subtitle',false,value);field('작품 설명','description',true,value);field('입장 주소 (비우면 기본 연결)','link',false,value);image('전시 이미지','image',value,p.image||'')}}
    fields.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=!access.canEdit);
  }
  editor.querySelectorAll('[data-editor-section]').forEach(b=>b.addEventListener('click',()=>{section=b.dataset.editorSection;editor.querySelectorAll('[data-editor-section]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()}));
  // Capture before the legacy display/link tab handler, which only knows two panels.
  tabs.addEventListener('click',event=>{const b=event.target.closest('[data-settings-tab]');if(!b)return;event.stopImmediatePropagation();for(const name of ['display','links','exhibition'])dialog.querySelector('#'+name+'-settings').hidden=b.dataset.settingsTab!==name;tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));dialog.classList.toggle('editing-exhibition',b.dataset.settingsTab==='exhibition');},true);
  editor.querySelector('#editor-preview').addEventListener('click',()=>dialog.close());
  editor.querySelector('#editor-discard').addEventListener('click',()=>{draft=structuredClone(saved);dirty=false;previewContent(draft);render();say('저장된 전시로 돌아왔습니다.')});
  editor.querySelector('#editor-save').disabled=!access.canEdit;
  editor.querySelector('#editor-save').addEventListener('click',async()=>{if(busy)return;busy=true;const button=editor.querySelector('#editor-save');button.disabled=true;say('전시를 저장하고 있습니다…');try{await saveContent(draft);saved=getContent();draft=getContent();dirty=false;render();say('저장했습니다. 방문자에게도 이 전시가 표시됩니다.')}catch(e){say(e.message,true)}finally{busy=false;button.disabled=false}});
  editor.querySelector('#content-export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'juho-museum-v1',content:draft},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-museum.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
  editor.querySelector('#content-import').disabled=!access.canEdit;
  editor.querySelector('#content-import').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('설정 파일이 너무 큽니다.');const value=JSON.parse(await f.text());if(value.format!=='juho-museum-v1')throw Error('전시 설정 파일을 선택해 주세요.');draft=cleanContent(value.content);changed();render()}catch(e){say(e.message,true)}finally{e.target.value=''}});
  editor.querySelector('#content-reset').disabled=!access.canEdit;
  editor.querySelector('#content-reset').addEventListener('click',()=>{draft=cleanContent();changed();render();say('기본 전시 미리보기입니다. 저장 전에는 기존 전시가 유지됩니다.')});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
  render();if(!access.canEdit)say(access.loadError||'전시 편집은 사이트 소유자로 로그인하면 사용할 수 있습니다.',true);
  tab.click();
}
